creds = apis.supervisor.show_account_passwords();
amazon_pw = [c['password'] for c in creds if c['account_name']=='amazon'][0]
login = apis.amazon.login(username='jepowell@gmail.com', password=amazon_pw)
token = login['access_token']
print('token_prefix', token[:10])
# fetch orders with query 'flip' pages
all_orders=[]
page_limit=20
page_index=0
while True:
    page = apis.amazon.show_orders(access_token=token, query='flip', page_index=page_index, page_limit=page_limit, sort_by='-created_at')
    print('page', page_index, 'type', type(page))
    batch = page if isinstance(page,list) else page.get('orders', []) if isinstance(page,dict) else []
    print('batch_len', len(batch))
    if not batch:
        break
    all_orders.extend(batch)
    if len(batch) < page_limit:
        break
    page_index += 1
print('total_orders_fetched', len(all_orders))
# filter order items with flip-flop in name
import re
pattern = re.compile(r'flip\s*-?\s*flop', re.IGNORECASE)
candidates=[]
for o in all_orders:
    for item in o.get('order_items', []):
        name = (item.get('product_name') or '')
        if pattern.search(name):
            candidates.append({
                'created_at': o.get('created_at'),
                'order_id': o.get('order_id'),
                'product_id': item.get('product_id'),
                'product_name': name,
                'ordered_quantity': item.get('ordered_quantity'),
                'returned_quantity': item.get('returned_quantity'),
                'delivered_at': item.get('delivered_at'),
                'expected_delivery_at': item.get('expected_delivery_at'),
            })
print('candidates_count', len(candidates))
# show top 5 newest by created_at
from datetime import datetime

def parse_dt(s):
    if not s:
        return datetime.min
    try:
        return datetime.fromisoformat(s.replace('Z',''))
    except Exception:
        try:
            return datetime.strptime(s, '%Y-%m-%dT%H:%M:%S')
        except Exception:
            return datetime.min

candidates_sorted = sorted(candidates, key=lambda c: parse_dt(c['created_at']), reverse=True)
print('top_candidates:')
for c in candidates_sorted[:5]:
    print(c)

